<?php
declare(strict_types=1);

final class RequestService {
    public function __construct(private PDO $db) {}

    public function createDraft(int $userId,?int $groupId,string $purpose,array $materialIds,array $quantities): int {
        $items=$this->normalizeItems($materialIds,$quantities); if(!$items)throw new DomainException('กรุณาเลือกวัสดุอย่างน้อย 1 รายการ');
        $this->db->beginTransaction();
        try{$this->assertAvailable($items);$this->db->prepare('INSERT INTO requisitions(requester_id,work_group_id,purpose) VALUES(?,?,?)')->execute([$userId,$groupId,$purpose]);$id=(int)$this->db->lastInsertId();$s=$this->db->prepare('INSERT INTO requisition_items(requisition_id,material_id,requested_qty) VALUES(?,?,?)');foreach($items as$mid=>$q)$s->execute([$id,$mid,$q]);$this->action($id,'create',null,'draft',null,$userId);$this->db->commit();return$id;}catch(Throwable$e){$this->db->rollBack();throw$e;}
    }

    public function updateDraft(int $id,int $userId,string $purpose,array $materialIds,array $quantities): void {
        $items=$this->normalizeItems($materialIds,$quantities);if(!$items)throw new DomainException('กรุณาเลือกวัสดุอย่างน้อย 1 รายการ');$this->db->beginTransaction();
        try{$r=$this->lockOwned($id,$userId);if(!in_array($r['status'],['draft','returned'],true))throw new DomainException('แก้ไขได้เฉพาะแบบร่างหรือรายการที่ส่งกลับ');$this->assertAvailable($items);$this->db->prepare('UPDATE requisitions SET purpose=? WHERE id=?')->execute([$purpose,$id]);$this->db->prepare('DELETE FROM requisition_items WHERE requisition_id=?')->execute([$id]);$s=$this->db->prepare('INSERT INTO requisition_items(requisition_id,material_id,requested_qty) VALUES(?,?,?)');foreach($items as$mid=>$q)$s->execute([$id,$mid,$q]);audit('request.update','requisition',$id,null,['items'=>count($items)]);$this->db->commit();}catch(Throwable$e){$this->db->rollBack();throw$e;}
    }

    public function submit(int $id,int $userId): void {
        $this->db->beginTransaction();try{$r=$this->lockOwned($id,$userId);if(!in_array($r['status'],['draft','returned'],true))throw new DomainException('สถานะนี้ส่งคำขอไม่ได้');$s=$this->db->prepare('SELECT material_id,requested_qty FROM requisition_items WHERE requisition_id=?');$s->execute([$id]);$items=[];foreach($s->fetchAll()as$i)$items[(int)$i['material_id']]=(float)$i['requested_qty'];if(!$items)throw new DomainException('คำขอไม่มีรายการวัสดุ');$this->assertAvailable($items);$no=$r['request_no']?:document_no(setting('request_prefix','REQ'));$this->db->prepare("UPDATE requisitions SET request_no=?,status='pending',submitted_at=NOW() WHERE id=?")->execute([$no,$id]);$this->action($id,'submit',$r['status'],'pending',null,$userId);$this->db->commit();}catch(Throwable$e){$this->db->rollBack();throw$e;}
    }

    public function cancel(int $id,int $userId,string $reason): void {
        $this->db->beginTransaction();try{$r=$this->lockOwned($id,$userId);if(!in_array($r['status'],['draft','pending','returned'],true))throw new DomainException('คำขอนี้ไม่สามารถยกเลิกได้');$this->db->prepare("UPDATE requisitions SET status='cancelled',cancelled_at=NOW() WHERE id=?")->execute([$id]);$this->action($id,'cancel',$r['status'],'cancelled',$reason,$userId);$this->db->commit();}catch(Throwable$e){$this->db->rollBack();throw$e;}
    }

    public function decide(int $id,string $decision,array $approved,string $reason,int $actor): void {
        $map=['approve'=>'approved','return'=>'returned','reject'=>'rejected'];if(!isset($map[$decision]))throw new DomainException('คำสั่งไม่ถูกต้อง');if($decision!=='approve'&&trim($reason)==='')throw new DomainException('กรุณาระบุเหตุผล');
        $this->db->beginTransaction();try{$s=$this->db->prepare('SELECT * FROM requisitions WHERE id=? FOR UPDATE');$s->execute([$id]);$r=$s->fetch();if(!$r||$r['status']!=='pending')throw new DomainException('คำขอไม่ได้อยู่ระหว่างอนุมัติ');
            if($decision==='approve'){$s=$this->db->prepare('SELECT * FROM requisition_items WHERE requisition_id=? FOR UPDATE');$s->execute([$id]);$up=$this->db->prepare('UPDATE requisition_items SET approved_qty=? WHERE id=?');$total=0.0;foreach($s->fetchAll()as$i){$q=round((float)($approved[$i['id']]??0),3);if($q<0||$q>(float)$i['requested_qty'])throw new DomainException('จำนวนอนุมัติต้องไม่เกินจำนวนขอ');$total+=$q;$up->execute([$q,$i['id']]);}if($total<=0)throw new DomainException('การอนุมัติต้องมีอย่างน้อยหนึ่งรายการมากกว่า 0 หรือเลือกไม่อนุมัติ');}
            $to=$map[$decision];$this->db->prepare('UPDATE requisitions SET status=?,approved_at=IF(?="approved",NOW(),approved_at) WHERE id=?')->execute([$to,$to,$id]);$this->action($id,$decision,'pending',$to,$reason,$actor);audit('request.'.$decision,'requisition',$id,$r,['status'=>$to]);$this->db->commit();
        }catch(Throwable$e){$this->db->rollBack();throw$e;}
    }

    public function issue(int $id,array $quantities,string $receiver,string $key,string $note,int $actor): int {
        if(!preg_match('/^[a-f0-9]{32,100}$/',$key))throw new DomainException('รหัสป้องกันรายการซ้ำไม่ถูกต้อง');$this->db->beginTransaction();
        try{$s=$this->db->prepare('SELECT id FROM issues WHERE idempotency_key=?');$s->execute([$key]);if($old=$s->fetchColumn()){$this->db->commit();return(int)$old;}
            $s=$this->db->prepare('SELECT * FROM requisitions WHERE id=? FOR UPDATE');$s->execute([$id]);$r=$s->fetch();if(!$r||!in_array($r['status'],['approved','partially_issued'],true))throw new DomainException('คำขอนี้จ่ายไม่ได้');$no=document_no('ISS');$this->db->prepare('INSERT INTO issues(issue_no,requisition_id,receiver_name,issued_by,idempotency_key,note) VALUES(?,?,?,?,?,?)')->execute([$no,$id,$receiver,$actor,$key,$note]);$issueId=(int)$this->db->lastInsertId();
            $s=$this->db->prepare('SELECT ri.*,m.stock_qty,m.track_assignee FROM requisition_items ri JOIN materials m ON m.id=ri.material_id WHERE ri.requisition_id=? ORDER BY ri.id FOR UPDATE');$s->execute([$id]);$made=false;
            foreach($s->fetchAll()as$i){$q=round((float)($quantities[$i['id']]??0),3);if($q<=0)continue;$remaining=(float)$i['approved_qty']-(float)$i['issued_qty'];if($q>$remaining)throw new DomainException('จำนวนจ่ายสะสมเกินจำนวนอนุมัติ');if($q>(float)$i['stock_qty'])throw new DomainException('ยอดคงเหลือไม่เพียงพอสำหรับ '.$i['material_id']);$this->db->prepare('INSERT INTO issue_items(issue_id,requisition_item_id,quantity) VALUES(?,?,?)')->execute([$issueId,$i['id'],$q]);$issueItemId=(int)$this->db->lastInsertId();$newStock=round((float)$i['stock_qty']-$q,3);$this->db->prepare('UPDATE materials SET stock_qty=?,version=version+1 WHERE id=?')->execute([$newStock,$i['material_id']]);$this->db->prepare('UPDATE requisition_items SET issued_qty=issued_qty+? WHERE id=?')->execute([$q,$i['id']]);$this->db->prepare("INSERT INTO stock_movements(material_id,movement_type,quantity_delta,balance_after,reference_type,reference_id,reference_no,created_by) VALUES(?,'issue',?,?,?,?,?,?)")->execute([$i['material_id'],-$q,$newStock,'issue_item',$issueItemId,$no,$actor]);if($i['track_assignee'])$this->db->prepare('INSERT INTO asset_assignments(material_id,requisition_item_id,assigned_user_id,quantity) VALUES(?,?,?,?)')->execute([$i['material_id'],$i['id'],$r['requester_id'],$q]);$made=true;}
            if(!$made)throw new DomainException('กรุณาระบุจำนวนจ่ายอย่างน้อยหนึ่งรายการ');$s=$this->db->prepare('SELECT COUNT(*) FROM requisition_items WHERE requisition_id=? AND issued_qty<approved_qty');$s->execute([$id]);$to=(int)$s->fetchColumn()?'partially_issued':'issued';$s=$this->db->prepare('SELECT COUNT(*) confirmed_count FROM issues i JOIN receipts_confirmation rc ON rc.issue_id=i.id WHERE i.requisition_id=?');$s->execute([$id]);$receiptStatus=(int)$s->fetchColumn()?'partially_received':'not_received';$this->db->prepare('UPDATE requisitions SET status=?,receipt_status=?,completed_at=NULL WHERE id=?')->execute([$to,$receiptStatus,$id]);$this->action($id,'issue',$r['status'],$to,$note,$actor);audit('request.issue','issue',$issueId,null,['request_id'=>$id]);$this->db->commit();return$issueId;
        }catch(Throwable$e){$this->db->rollBack();if($e instanceof PDOException&&$e->getCode()==='23000'){ $s=$this->db->prepare('SELECT id FROM issues WHERE idempotency_key=?');$s->execute([$key]);if($old=$s->fetchColumn())return(int)$old;}throw$e;}
    }

    public function close(int $id,string $reason,int $actor): void {if(trim($reason)==='')throw new DomainException('กรุณาระบุเหตุผลปิดยอด');$this->db->beginTransaction();try{$s=$this->db->prepare('SELECT * FROM requisitions WHERE id=? FOR UPDATE');$s->execute([$id]);$r=$s->fetch();if(!$r||$r['status']!=='partially_issued')throw new DomainException('ปิดยอดได้เฉพาะคำขอที่จ่ายบางส่วน');$s=$this->db->prepare('SELECT COUNT(*) FROM issues i LEFT JOIN receipts_confirmation rc ON rc.issue_id=i.id WHERE i.requisition_id=? AND rc.id IS NULL');$s->execute([$id]);$completed=(int)$s->fetchColumn()===0;$this->db->prepare("UPDATE requisitions SET status='closed',close_reason=?,completed_at=IF(?,NOW(),NULL) WHERE id=?")->execute([$reason,$completed?1:0,$id]);$this->action($id,'close',$r['status'],'closed',$reason,$actor);audit('request.close','requisition',$id,$r,['reason'=>$reason,'completed'=>$completed]);$this->db->commit();}catch(Throwable$e){$this->db->rollBack();throw$e;}}
    public function confirmReceipt(int $issueId,int $userId): void {$this->db->beginTransaction();try{$s=$this->db->prepare('SELECT i.id,i.requisition_id,r.requester_id,r.status,r.completed_at FROM issues i JOIN requisitions r ON r.id=i.requisition_id WHERE i.id=? FOR UPDATE');$s->execute([$issueId]);$i=$s->fetch();if(!$i||(int)$i['requester_id']!==$userId)throw new DomainException('ไม่พบรายการจ่ายของคุณ');$s=$this->db->prepare('SELECT id FROM receipts_confirmation WHERE issue_id=?');$s->execute([$issueId]);if($s->fetchColumn()){$this->db->commit();return;}$this->db->prepare('INSERT INTO receipts_confirmation(issue_id,confirmed_by) VALUES(?,?)')->execute([$issueId,$userId]);$s=$this->db->prepare('SELECT COUNT(*) FROM issues i LEFT JOIN receipts_confirmation rc ON rc.issue_id=i.id WHERE i.requisition_id=? AND rc.id IS NULL');$s->execute([$i['requisition_id']]);$pending=(int)$s->fetchColumn();$status=$pending?'partially_received':'received';$isComplete=$pending===0&&in_array($i['status'],['issued','closed'],true);$this->db->prepare('UPDATE requisitions SET receipt_status=?,completed_at=IF(?,NOW(),NULL) WHERE id=?')->execute([$status,$isComplete?1:0,$i['requisition_id']]);if($isComplete&&!$i['completed_at'])$this->action((int)$i['requisition_id'],'complete',$i['status'],'completed','ผู้เบิกยืนยันรับของครบแล้ว',$userId);audit('request.receive_confirm','issue',$issueId,null,['confirmed'=>true,'request_completed'=>$isComplete]);$this->db->commit();}catch(Throwable$e){$this->db->rollBack();throw$e;}}
    private function normalizeItems(array $ids,array $qs): array {$out=[];foreach($ids as$k=>$raw){$id=(int)$raw;$q=round((float)($qs[$k]??0),3);if($id>0&&$q>0)$out[$id]=($out[$id]??0)+$q;}return$out;}
    private function assertAvailable(array $items):void{$ids=array_map('intval',array_keys($items));$marks=implode(',',array_fill(0,count($ids),'?'));$s=$this->db->prepare("SELECT id,name,stock_qty,active FROM materials WHERE id IN ($marks)");$s->execute($ids);$found=[];foreach($s->fetchAll()as$m){$found[(int)$m['id']]=true;if(!(int)$m['active'])throw new DomainException('วัสดุ '.$m['name'].' ปิดรับคำขอแล้ว');if((float)$m['stock_qty']<=0)throw new DomainException('วัสดุ '.$m['name'].' หมดสต๊อก ไม่สามารถเบิกได้');}if(count($found)!==count($ids))throw new DomainException('ไม่พบวัสดุบางรายการ');}
    private function lockOwned(int$id,int$userId):array{$s=$this->db->prepare('SELECT * FROM requisitions WHERE id=? AND requester_id=? FOR UPDATE');$s->execute([$id,$userId]);$r=$s->fetch();if(!$r)throw new DomainException('ไม่พบคำขอหรือคุณไม่มีสิทธิ์');return$r;}
    private function action(int$id,string$action,?string$from,string$to,?string$reason,int$actor):void{$this->db->prepare('INSERT INTO requisition_actions(requisition_id,action,from_status,to_status,reason,actor_id) VALUES(?,?,?,?,?,?)')->execute([$id,$action,$from,$to,$reason,$actor]);}
}
